#include <stdio.h>

/* teste do desafio saudacao-tres-vezes — counter_protocol (03-tdd 3.9.3).
   Dois cenarios, duas capturas: cada um manda o stdout para o SEU arquivo
   temporario com freopen, chama a funcao do aluno e le o arquivo de volta.
   O fflush descarrega sem fechar — e por isso o segundo freopen e legal. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
void saudacao(void);
void saudacaoTresVezes(void);

SM_TEST(tres_chamadas_tres_linhas) {
    freopen("sm_saida_1.tmp", "w", stdout);
    saudacaoTresVezes();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha", linha, "bom dia, mundo\n",
              "a primeira chamada roda o corpo da caixa saudacao");
    fgets(linha, 80, f);
    checa_str("a segunda linha", linha, "bom dia, mundo\n",
              "a segunda chamada roda o MESMO corpo outra vez");
    fgets(linha, 80, f);
    checa_str("a terceira linha", linha, "bom dia, mundo\n",
              "a terceira chamada fecha as tres execucoes");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha quarta linha", fim, "(nada impresso)",
              "sao tres chamadas: a saida acaba na terceira linha");
    fclose(f);
}

SM_TEST(a_caixa_pronta_segue_com_uma_linha) {
    freopen("sm_saida_2.tmp", "w", stdout);
    saudacao();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha da caixa saudacao", linha, "bom dia, mundo\n",
              "a caixa pronta continua imprimindo a sua linha");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("a caixa pronta nao ganhou linha", fim, "(nada impresso)",
              "quem repete e quem chama: a caixa imprime uma linha so");
    fclose(f);
}

